#!/bin/bash
set -uo pipefail
PIN=e47afdde7fb
git fetch -q origin 2>/dev/null || true
CUR=$(git rev-parse HEAD)
if [ "$CUR" != "$PIN" ] && ! git rev-parse HEAD | grep -q "^$PIN"; then echo "PIN: was $CUR"; git checkout -f -q "$PIN" || { echo PIN-FAILED; exit 3; }; fi
mkdir -p src/v2/test/claim/manual
echo '' | base64 -d > src/v2/test/claim/manual/record_under_unary_probe_tmp.dag
echo STEP build; date -u +%H:%M:%S
cargo build --release -p v1-compiler --bin claim_batch 2>&1 | tail -1
./target/release/claim_batch --source-root src --source-root src/v1 --source-root src/v2 --source-root dag   --entry src/v2/test/claim/manual/record_under_unary_probe_tmp.dag --function record_under_unary_probe_reports > /tmp/rp.log 2>&1
echo "probe rc=$?"
grep -aE 'RECORD-UNDER-UNARY|plain_record|minus_record|bang_record|add_record|mul_record|resolve failed' /tmp/rp.log | head -12 | cut -c1-200
rm -f src/v2/test/claim/manual/record_under_unary_probe_tmp.dag
echo "=== DONE ==="
